/* ── physics + state ────────────────────────────────────────────────────── */
const KMG = 42 / (1.8e-3 * 0.8 * 0.8);   // mg per (χ·B²), calibrated to +42 mg at 0.8 T
const DM_MAX = KMG * 1.8e-3 * 1.5 * 1.5; // ≈148 mg
const S = { sample: 'para', B: 0.8, comp: 0 };
let bTarget = 0.8;
let tiltCur = 0, tiltVel = 0;
const dropT = [-1, -1];

function chiOf() { return S.sample === 'para' ? 1.8e-3 : -2.5e-5; }
function deltaM() { return KMG * chiOf() * S.B * S.B; }
function tiltTarget() {
  const dm = deltaM();
  const f = Math.pow(Math.min(1, Math.abs(dm) / DM_MAX), 0.35);
  return Math.sign(dm) * THREE.MathUtils.degToRad(8) * f * (1 - S.comp);
}

function updateField() {
  const b = S.B;
  const op = b <= 0.001 ? 0 : Math.min(0.95, 0.35 + 0.6 * (b / 1.5));
  matField.opacity = op;
  fieldGroup.visible = b > 0.001;
  fieldGroup.children.forEach(ch => { ch.visible = b > (ch.userData.thr || 0); });
}

function applyTilt() {
  pivot.rotation.z = tiltCur;
  tubeGrp.rotation.z = -tiltCur;
  panGrp.rotation.z = -tiltCur;
  const dm = deltaM();
  const pull = -0.05 * Math.sign(dm) * Math.min(1, Math.abs(dm) / DM_MAX);
  tubeGrp.position.set(-3.6, pull, 0);
}

const elRead = document.getElementById('readout');
const elB = document.getElementById('bVal');
const sldB = document.getElementById('sldB');
function updateReadout() {
  const dm = deltaM();
  const chiTxt = S.sample === 'para' ? '+1.8 × 10⁻³' : '−2.5 × 10⁻⁵';
  const sign = S.sample === 'para' ? 'χ &gt; 0 · paramagnetic' : 'χ &lt; 0 · diamagnetic';
  const dmTxt = (dm >= 0 ? '+' : '−') + Math.abs(dm).toFixed(dm !== 0 && Math.abs(dm) < 10 ? 2 : 1) + ' mg';
  const dir = dm > 0.0001 ? 'sample arm DOWN (heavier)' : dm < -0.0001 ? 'sample arm UP (lighter)' : 'beam level';
  elRead.innerHTML =
    `<b>${sign}</b><br>` +
    `χ = ${chiTxt}<br>` +
    `B = ${S.B.toFixed(2)} T<br>` +
    `F = χAB²/2μ₀ &nbsp; (∝ B²)<br>` +
    `Δm<sub>app</sub> = <b>${dmTxt}</b><br>` +
    `${dir}<br>` +
    `weights added: ${S.comp > 0.5 ? (S.comp >= 0.99 ? 2 : 1) : 0}` +
    `<div style="color:#777;margin-top:3px">beam deflection drawn on a<br>compressed scale so the tiny<br>diamagnetic tilt stays visible</div>`;
  elB.textContent = S.B.toFixed(2);
  sldB.value = S.B.toFixed(2);
}

