// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per element) ────────────────────────────────────
 base plate        → CylinderGeometry(1.3,1.3,0.18,56)        bright brass #EFD84B
 base rim          → TorusGeometry(1.3,0.045)                 brass dark
 support column    → CylinderGeometry(0.12,0.12,4.12,28)      brass
 fulcrum tip       → ConeGeometry(0.135,0.22,24)              brass dark
 balance beam      → CylinderGeometry(0.05,0.05,5.4) rotZ     brass (pivot group)
 hooks (2)         → TorusGeometry(0.14,0.045)                brass
 suspension wire   → CylinderGeometry(0.015,0.015,1.2)        black
 glass tube        → Cyl(0.24,h2.20)+halfSphere(0.24)+lip Cyl(0.33,0.10)  #D7ECEF 28%
 blue sample       → Cyl(0.215,h1.70)+halfSphere(0.215)       #5B7FE0 / top #8FA8F0
 magnet poles (2)  → CylinderGeometry(0.60,0.60,0.90,48) rotZ, grey gradient + black outline
 pole seam rings   → LineLoop circle black, 0.25 in from inner face
 field arcs (6)    → TubeGeometry(CatmullRomCurve3 ellipse, r 0.028)  #8A4FD8
 arc arrowheads    → ConeGeometry(0.075,0.18,8)               #8A4FD8
 gap arrows (18)   → Cylinder shaft + Cone head, into each pole face, z=+0.33
 fan arrows        → Cylinder shaft + Cone head, heads INTO each pole
 pan cords (4)     → CylinderGeometry(0.012)                  black
 weighing pan      → open frustum + disc + rim Torus          brass
 weights (3 + 2)   → CylinderGeometry(0.13,0.13,0.26)         silver #C9CBCE
 leader lines      → THREE.Line black
 labels            → addLabel 18px bold: Sample / Magnetic field / Electromagnets
──────────────────────────────────────────────────────────────────────────── */

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xe6e6e6, 2.0));
const gbKey = new THREE.DirectionalLight(0xffffff, 1.5);
gbKey.position.set(-4, 6, 7);
scene.add(gbKey);
const gbFill = new THREE.DirectionalLight(0xffffff, 0.6);
gbFill.position.set(5, 2, 5);
scene.add(gbFill);

/* ── materials ──────────────────────────────────────────────────────────── */
const matBrass = new THREE.MeshStandardMaterial({
  color: 0xEFD84B, metalness: 0.05, roughness: 0.48, emissive: 0x3d3608, emissiveIntensity: 1.0
});
const matBrass2 = new THREE.MeshStandardMaterial({
  color: 0xEFD84B, metalness: 0.05, roughness: 0.48, emissive: 0x3d3608,
  emissiveIntensity: 1.0, side: THREE.DoubleSide
});
const matBrassDark = new THREE.MeshStandardMaterial({
  color: 0xC9B234, metalness: 0.05, roughness: 0.55, emissive: 0x2e2906
});
const matBlack = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6, metalness: 0.0 });
const matSilver = new THREE.MeshStandardMaterial({ color: 0xCFD1D4, metalness: 0.12, roughness: 0.42 });
const matGlass = new THREE.MeshPhysicalMaterial({
  color: 0xD7ECEF, transparent: true, opacity: 0.26, roughness: 0.08,
  metalness: 0.0, depthWrite: false, side: THREE.DoubleSide
});
const matSample = new THREE.MeshStandardMaterial({ color: 0x5B7FE0, roughness: 0.42, metalness: 0.02 });
const matSampleTop = new THREE.MeshStandardMaterial({ color: 0x8FA8F0, roughness: 0.4 });
const matField = new THREE.MeshBasicMaterial({ color: 0x8A4FD8, transparent: true, opacity: 1.0 });
const matLeader = new THREE.LineBasicMaterial({ color: 0x000000 });
const matOutline = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide });

/* grey banded gradient for the pole pieces */
const gbCvs = document.createElement('canvas'); gbCvs.width = 256; gbCvs.height = 4;
{
  const cx2 = gbCvs.getContext('2d');
  const g = cx2.createLinearGradient(0, 0, 256, 0);
  g.addColorStop(0.00, '#9A9A9A'); g.addColorStop(0.18, '#F2F2F2');
  g.addColorStop(0.42, '#D2D2D2'); g.addColorStop(0.62, '#8F8F8F');
  g.addColorStop(0.82, '#E4E4E4'); g.addColorStop(1.00, '#9A9A9A');
  cx2.fillStyle = g; cx2.fillRect(0, 0, 256, 4);
}
const gbTex = new THREE.CanvasTexture(gbCvs);
const matMagnet = new THREE.MeshStandardMaterial({ map: gbTex, roughness: 0.5, metalness: 0.08 });

/* ── helpers ────────────────────────────────────────────────────────────── */
const UPY = new THREE.Vector3(0, 1, 0);
function gbRod(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(UPY, dir.clone().normalize());
  return m;
}
function gbArrow(pos, dir, size, mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(size * 0.42, size, 10), mat);
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(UPY, dir.clone().normalize());
  return m;
}
function gbCircleYZ(x, r, col) {
  const pts = [];
  for (let i = 0; i <= 64; i++) { const t = i / 64 * Math.PI * 2; pts.push(new THREE.Vector3(x, r * Math.cos(t), r * Math.sin(t))); }
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: col }));
}

/* ── stand: base, column, fulcrum ───────────────────────────────────────── */
const stand = new THREE.Group(); scene.add(stand);
const base = new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.3, 0.18, 56), matBrass);
base.position.set(1.2, 0.09, 0); stand.add(base);
const baseRim = new THREE.Mesh(new THREE.TorusGeometry(1.3, 0.045, 8, 56), matBrassDark);
baseRim.rotation.x = Math.PI / 2; baseRim.position.set(1.2, 0.09, 0); stand.add(baseRim);
const column = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 4.12, 28), matBrass);
column.position.set(1.2, 0.18 + 2.06, 0); stand.add(column);
const fulcrum = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.22, 24), matBrassDark);
fulcrum.position.set(1.2, 4.39, 0); stand.add(fulcrum);

/* ── pivot group (beam + everything suspended) ──────────────────────────── */
const pivot = new THREE.Group();
pivot.position.set(1.2, 4.45, 0);
scene.add(pivot);

const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 5.4, 20), matBrass);
beam.rotation.z = Math.PI / 2; beam.position.set(-0.9, 0, 0);
pivot.add(beam);
[-3.6, 1.8].forEach(x => {
  const hk = new THREE.Mesh(new THREE.TorusGeometry(0.14, 0.042, 10, 32), matBrass);
  hk.position.set(x, 0.13, 0); pivot.add(hk);
  const stub = new THREE.Mesh(new THREE.CylinderGeometry(0.048, 0.048, 0.14, 12), matBrass);
  stub.position.set(x, 0.02, 0); pivot.add(stub);
});

/* ── left arm: wire + sample tube (plumb sub-group) ─────────────────────── */
const tubeGrp = new THREE.Group(); tubeGrp.position.set(-3.6, 0, 0); pivot.add(tubeGrp);
tubeGrp.add(gbRod(new THREE.Vector3(0, 0.05, 0), new THREE.Vector3(0, -1.20, 0), 0.015, matBlack));

/* sample liquid (added before glass so glass renders over it) */
const liq = new THREE.Mesh(new THREE.CylinderGeometry(0.215, 0.215, 1.70, 30), matSample);
liq.position.set(0, -2.55, 0); tubeGrp.add(liq);
const liqBot = new THREE.Mesh(new THREE.SphereGeometry(0.215, 30, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), matSample);
liqBot.position.set(0, -3.40, 0); tubeGrp.add(liqBot);
const liqTop = new THREE.Mesh(new THREE.CylinderGeometry(0.215, 0.215, 0.03, 30), matSampleTop);
liqTop.position.set(0, -1.70, 0); tubeGrp.add(liqTop);

/* glass */
const glassBody = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 2.20, 34, 1, true), matGlass);
glassBody.position.set(0, -2.30, 0); glassBody.renderOrder = 5; tubeGrp.add(glassBody);
const glassBot = new THREE.Mesh(new THREE.SphereGeometry(0.24, 34, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), matGlass);
glassBot.position.set(0, -3.40, 0); glassBot.renderOrder = 5; tubeGrp.add(glassBot);
const glassLip = new THREE.Mesh(new THREE.CylinderGeometry(0.33, 0.33, 0.10, 34), matGlass);
glassLip.position.set(0, -1.20, 0); glassLip.renderOrder = 6; tubeGrp.add(glassLip);
const lipRing = new THREE.Mesh(new THREE.TorusGeometry(0.33, 0.024, 8, 44),
  new THREE.MeshStandardMaterial({ color: 0xAFCDD3, roughness: 0.3 }));
lipRing.rotation.x = Math.PI / 2; lipRing.position.set(0, -1.15, 0); tubeGrp.add(lipRing);

/* ── right arm: cords + pan + weights (plumb sub-group) ─────────────────── */
const panGrp = new THREE.Group(); panGrp.position.set(1.8, 0, 0); pivot.add(panGrp);
const hookPt = new THREE.Vector3(0, 0.05, 0);
for (let i = 0; i < 4; i++) {
  const a = Math.PI / 4 + i * Math.PI / 2;
  panGrp.add(gbRod(hookPt, new THREE.Vector3(0.68 * Math.cos(a), -1.60, 0.68 * Math.sin(a)), 0.012, matBlack));
}
const panWall = new THREE.Mesh(new THREE.CylinderGeometry(0.70, 0.54, 0.15, 44, 1, true), matBrass2);
panWall.position.set(0, -1.60, 0); panGrp.add(panWall);
const panBottom = new THREE.Mesh(new THREE.CylinderGeometry(0.54, 0.54, 0.02, 44), matBrassDark);
panBottom.position.set(0, -1.675, 0); panGrp.add(panBottom);
const panRim = new THREE.Mesh(new THREE.TorusGeometry(0.70, 0.035, 8, 48), matBrassDark);
panRim.rotation.x = Math.PI / 2; panRim.position.set(0, -1.525, 0); panGrp.add(panRim);

const weightRest = -1.545;
const weightPos = [[-0.19, 0.09], [0.15, 0.13], [0.00, -0.19], [-0.32, -0.12], [0.33, -0.08]];
const weights = weightPos.map((p, i) => {
  const w = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.26, 22), matSilver);
  w.position.set(p[0], weightRest, p[1]);
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 0.07, 18),
    new THREE.MeshStandardMaterial({ color: 0xE4E6E9, metalness: 0.12, roughness: 0.35 }));
  cap.position.y = 0.15; w.add(cap);
  if (i >= 3) w.visible = false;
  panGrp.add(w);
  return w;
});

/* ── electromagnets: round cylinders facing across a narrow open gap ────── */
const POLE_R = 0.60, POLE_L = 0.90;
const POLE_LX = -3.15, POLE_RX = -1.65;   // inner faces at -2.70 / -2.10  → gap 0.60
const POLE_Y = 1.95;
const magnets = new THREE.Group(); scene.add(magnets);
function makeMagnet(cx, innerSign) {
  const g = new THREE.Group();
  const geo = new THREE.CylinderGeometry(POLE_R, POLE_R, POLE_L, 48, 1, false);
  geo.rotateZ(Math.PI / 2);
  const body = new THREE.Mesh(geo, matMagnet);
  g.add(body);
  const outl = new THREE.Mesh(geo.clone().scale(1.012, 1.02, 1.02), matOutline);
  g.add(outl);
  [-POLE_L / 2, POLE_L / 2, innerSign * (POLE_L / 2 - 0.25)].forEach(x => g.add(gbCircleYZ(x, POLE_R + 0.004, 0x000000)));
  g.position.set(cx, POLE_Y, 0);
  registerInteractive(body, {
    title: 'Electromagnet pole piece',
    tooltip: 'Electromagnet pole',
    body: 'Two cylindrical poles face each other across a narrow open gap. The field there is strong and strongly inhomogeneous — it is the gradient of B², not B alone, that produces the force on the sample.'
  });
  return g;
}
magnets.add(makeMagnet(POLE_LX, +1));
magnets.add(makeMagnet(POLE_RX, -1));

/* ── magnetic field lines ───────────────────────────────────────────────── */
const fieldGroup = new THREE.Group(); scene.add(fieldGroup);
const GAPX = -2.4, GAPY = POLE_Y;
const FACE_L = POLE_LX + POLE_L / 2;   // -2.70
const FACE_R = POLE_RX - POLE_L / 2;   // -2.10

/* nested dipole arcs, arching well above and below the poles */
for (let i = 0; i < 6; i++) {
  const ax = 0.32 + i * 0.062;          // 0.32 → 0.63
  const ay = 0.62 + i * 0.175;          // 0.62 → 1.50
  const pts = [];
  for (let k = 0; k < 96; k++) {
    const t = k / 96 * Math.PI * 2;
    pts.push(new THREE.Vector3(GAPX + ax * Math.cos(t), GAPY + ay * Math.sin(t), 0));
  }
  const curve = new THREE.CatmullRomCurve3(pts, true);
  const tubeMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 180, 0.028, 7, true), matField);
  tubeMesh.userData.thr = i * 0.10;
  fieldGroup.add(tubeMesh);
  [0.07, 0.20, 0.30, 0.43, 0.57, 0.70, 0.80, 0.93].forEach(u => {
    const p = curve.getPointAt(u), tg = curve.getTangentAt(u);
    const a = gbArrow(p, tg, 0.18, matField);
    a.userData.thr = i * 0.10;
    fieldGroup.add(a);
  });
  registerInteractive(tubeMesh, {
    title: 'Magnetic field line',
    tooltip: 'Inhomogeneous field in the gap',
    body: 'Purple arcs trace the flux leaving one pole and curling back into the other. The lines crowd together inside the gap, so B — and its gradient — is largest exactly where the bottom of the sample hangs.'
  });
}

/* dense horizontal arrows crossing the gap, drawn in front of the tube */
for (let y = -0.66; y <= 0.661; y += 0.1467) {
  const yy = GAPY + y;
  // into the LEFT pole face
  let sh = gbRod(new THREE.Vector3(GAPX - 0.02, yy, 0.33), new THREE.Vector3(FACE_L + 0.10, yy, 0.33), 0.016, matField);
  sh.userData.thr = 0.03; fieldGroup.add(sh);
  let hd = gbArrow(new THREE.Vector3(FACE_L + 0.06, yy, 0.33), new THREE.Vector3(-1, 0, 0), 0.13, matField);
  hd.userData.thr = 0.03; fieldGroup.add(hd);
  // into the RIGHT pole face
  sh = gbRod(new THREE.Vector3(GAPX + 0.02, yy, 0.33), new THREE.Vector3(FACE_R - 0.10, yy, 0.33), 0.016, matField);
  sh.userData.thr = 0.03; fieldGroup.add(sh);
  hd = gbArrow(new THREE.Vector3(FACE_R - 0.06, yy, 0.33), new THREE.Vector3(1, 0, 0), 0.13, matField);
  hd.userData.thr = 0.03; fieldGroup.add(hd);
}

/* fan arrows around the outside of each pole, all heads pointing INTO the pole */
[[POLE_LX, 180], [POLE_RX, 0]].forEach(([px, outDeg]) => {
  [0.98, 1.42, 1.86].forEach((r, ri) => {
    for (let da = -130; da <= 130; da += 20) {
      const ang = THREE.MathUtils.degToRad(outDeg + da);
      const dir = new THREE.Vector3(Math.cos(ang), Math.sin(ang), 0);
      const c = new THREE.Vector3(px, POLE_Y, 0);
      const outer = c.clone().addScaledVector(dir, r + 0.26);
      const inner = c.clone().addScaledVector(dir, r - 0.10);
      const shaft = gbRod(outer, inner, 0.020, matField);
      shaft.userData.thr = ri === 0 ? 0.15 : (ri === 1 ? 0.5 : 0.95);
      fieldGroup.add(shaft);
      const head = gbArrow(inner, dir.clone().negate(), 0.17, matField);
      head.userData.thr = shaft.userData.thr;
      fieldGroup.add(head);
    }
  });
});

/* ── leader lines for the labels ────────────────────────────────────────── */
function leader(points) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points.map(p => new THREE.Vector3(...p))), matLeader);
  scene.add(l); return l;
}
leader([[-3.28, 3.32, 0.45], [-2.66, 2.92, 0.45]]);                        // Sample
leader([[-1.40, 3.62, 0.45], [-1.95, 3.10, 0.45]]);                        // Magnetic field
leader([[-3.15, 1.38, 0.45], [-2.40, 0.58, 0.45], [-1.65, 1.38, 0.45]]);   // Electromagnets

/* ── camera (after all geometry) — nearly front-on, as printed ──────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 78, elevationDeg: 7, rollDeg: 0,
  target: [-0.15, 2.35, 0],
  heightFraction: 0.80, distanceScale: 1.5
});

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('Sample', new THREE.Vector3(-4.05, 3.36, 0.45), { fontSize: '19px', bold: true });
addLabel('Magnetic<br>field', new THREE.Vector3(-1.02, 3.92, 0.45), { fontSize: '19px', bold: true });
addLabel('Electromagnets', new THREE.Vector3(-2.40, 0.24, 0.45), { fontSize: '19px', bold: true });

/* ── interactive extras ─────────────────────────────────────────────────── */
registerInteractive(liq, {
  title: 'Sample',
  tooltip: 'Sample in the glass tube',
  body: 'The sample sits in the bottom of a thin glass tube suspended from the balance beam so its lower part lies in the intense field of the gap while its top is essentially field-free.'
