  const dt = Math.min(0.05, (now - gbLast) / 1000); gbLast = now;
  if (anim.running) updateAnim(dt);
  S.B += (bTarget - S.B) * Math.min(1, dt * 7);
  if (Math.abs(bTarget - S.B) < 0.002) S.B = bTarget;
  const tgt = tiltTarget();
  tiltVel += (tgt - tiltCur) * 60 * dt - tiltVel * 5.0 * dt;
  tiltCur += tiltVel * dt;
  applyTilt();
  updateField();
  updateReadout();
}
gbTick();

/* ── controls ───────────────────────────────────────────────────────────── */
const btnPara = document.getElementById('btnPara');
const btnDia = document.getElementById('btnDia');
function setSample(kind, keepAnim) {
  S.sample = kind;
  btnPara.classList.toggle('active', kind === 'para');
  btnDia.classList.toggle('active', kind === 'dia');
