  bTarget = parseFloat(sldB.value);
});

document.getElementById('btnRun').addEventListener('click', startRun);

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Magnet off — beam level', narr: 'With no current in the electromagnets the tube hangs freely in the gap and the beam balances against the calibrated weights. χ cannot yet be read.', B: 0, s: 'para', comp: 0 },
  { title: 'Energize the magnet — paramagnetic pull', narr: 'At 0.8 T the paramagnetic sample is drawn down into the strongest part of the inhomogeneous field; the sample arm dips and the sample appears heavier (χ > 0).', B: 0.8, s: 'para', comp: 0 },
  { title: 'Stronger field, larger deflection', narr: 'Raising B to 1.5 T increases the downward force roughly as B², so the beam tips further — but the susceptibility extracted from it is unchanged.', B: 1.5, s: 'para', comp: 0 },
  { title: 'Swap in a diamagnetic sample', narr: 'With all electrons paired the sample is weakly expelled from the field: the sample arm rises slightly, the apparent mass decreases, and χ is small and negative.', B: 1.5, s: 'dia', comp: 0 },
  { title: 'Re-level with calibrated weights', narr: 'Weights are added until the beam is level again; the mass difference is proportional to χ and hence to the number of unpaired electrons.', B: 0.8, s: 'para', comp: 1 }
];
let stepIdx = 0;
const elTitle = document.getElementById('stepTitle');
const elNarr = document.getElementById('stepNarr');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  anim.running = false;
  setSample(st.s, true);
  bTarget = st.B;
  S.comp = st.comp;
  weights[3].visible = st.comp > 0;
  weights[4].visible = st.comp >= 1;
  weights[3].position.y = weightRest; weights[4].position.y = weightRest;
  elTitle.textContent = (stepIdx + 1) + '. ' + st.title;
  elNarr.textContent = st.narr;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

document.getElementById('btnReset').style.display = '';
document.getElementById('btnReset').textContent = '⟲ Reset view';

goToStep(0);
bTarget = 0.8; S.B = 0.8;
elTitle.textContent = '1. ' + STEPS[0].title;
elNarr.textContent = STEPS[0].narr;
S.comp = 0;
updateReadout();
// @FIGURE_CODE_END

