const KMG = 42 / (1.8e-3 * 0.8 * 0.8);   // mg per (χ·B²), calibrated to +42 mg at 0.8 T
const DM_MAX = KMG * 1.8e-3 * 1.5 * 1.5; // ≈148 mg
const S = { sample: 'para', B: 0.8, comp: 0 };
let bTarget = 0.8;
let tiltCur = 0, tiltVel = 0;
